materialized.schema:
type FolderNode {
    id: String!
    name: String!
    kind: String!
    parentFolder: String
}

type FileNode {
    id: String!
    name: String!
    kind: String!
    documentType: String!
    parentFolder: String
}

union Node = FolderNode | FileNode

type DocumentDriveState {
    name: String!
    nodes: [Node!]! @deprecated(reason: "Use the reactor-drive subgraph (`reactorDrive.rootNodes`, `ReactorDriveFolderNode.children`) for paged listings.")
    icon: String
}

type ListenerFilter {
    documentType: [String!]
    documentId: [ID!]
    scope: [String!]
    branch: [String!]
}

enum TransmitterType {
    Internal,
    SwitchboardPush,
    PullResponder,
    SecureConnect, 
    MatrixConnect,
    RESTWebhook
}

type ListenerCallInfo {
    transmitterType: TransmitterType
    name: String
    data: String
}

type Listener {
    listenerId: ID!
    label: String
    block: Boolean!
    system: Boolean!
    filter: ListenerFilter!
    callInfo: ListenerCallInfo
}

enum TriggerType {
    PullResponder
}

type PullResponderTriggerData {
    listenerId: ID!
    url: String!
    interval: String!
}

union TriggerData = PullResponderTriggerData

type Trigger {
    id: ID!
    type: TriggerType!
    data: TriggerData
}

type DocumentDriveLocalState{
    sharingType: String
    listeners: [Listener!]!
    triggers: [Trigger!]!
    availableOffline: Boolean!
}
